-- Additive migration: command definitions are immutable per (mode,code,version).
-- No real capability, network endpoint, or physical operation is enabled here.
CREATE TABLE mx_device.command_definitions (
 id text PRIMARY KEY, mode text NOT NULL CHECK(mode='sim'), code text NOT NULL,
 version integer NOT NULL CHECK(version>0), document jsonb NOT NULL,
 UNIQUE(mode,code,version),
 CHECK(document->>'id'=id AND document->>'mode'=mode AND document->>'code'=code AND (document->>'version')::integer=version)
);
CREATE INDEX command_definitions_latest ON mx_device.command_definitions(mode,code,version DESC);
