-- One-time backfill freezes existing task definitions to the code they used before
-- editable command versions existed. Preserve their code, repeat and input fields.
UPDATE mx_device.task_definitions d
SET document = jsonb_set(d.document, '{steps}', (
 SELECT jsonb_agg(CASE
   WHEN NOT (s.step ? 'commandDefinition') AND c.document IS NOT NULL
   THEN s.step || jsonb_build_object('commandVersion', 1, 'commandDefinition', c.document)
   ELSE s.step END ORDER BY s.ordinal)
 FROM jsonb_array_elements(d.document->'steps') WITH ORDINALITY AS s(step,ordinal)
 LEFT JOIN mx_device.command_definitions c ON c.mode=d.mode AND c.code=s.step->>'code' AND c.version=1
))
WHERE EXISTS (
 SELECT 1 FROM jsonb_array_elements(d.document->'steps') s(step)
 WHERE NOT (s.step ? 'commandDefinition')
);
